package org.eclipse.rdf4j.query.algebra.evaluation.function.string;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.junit.jupiter.api.Test;

class EncodeForUriTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private final EncodeForUri function = new EncodeForUri();

	@Test
	void encodesSupplementaryCharactersAsUtf8() {
		assertEquals("%F0%9F%98%80", function.evaluate(VF, VF.createLiteral("😀")).getLabel());
	}

	@Test
	void preservesAsciiUnreservedCharactersAroundSupplementaryCharacters() {
		assertEquals("A-._~%F0%9F%98%80%20%2F",
				function.evaluate(VF, VF.createLiteral("A-._~😀 /")).getLabel());
	}
}
